@page "/recipes/{Category}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes</PageTitle>

<h1>@Category Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="list-group">
        @foreach (var recipe in recipes)
        {
            <a href="/recipe/@recipe.Id" class="list-group-item list-group-item-action">
                <div class="d-flex w-100 justify-content-between">
                    <h5 class="mb-1">@recipe.Title</h5>
                    <small>⭐ @recipe.AverageRating (@recipe.RatingCount ratings)</small>
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private IReadOnlyList<RecipeCommunity.Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <p><span class="badge bg-secondary">@recipe.Category</span></p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.Contains(". ") ? step[(step.IndexOf(". ") + 2)..] : step;
            <li>@text</li>
        }
    </ol>

    <h3>Rating</h3>
    <p>⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)</p>

    <StarRating RecipeId="recipe.Id" />
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="my-3">
    <p><strong>Rate this recipe:</strong></p>
    <div class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link fs-4 p-0 me-1 text-decoration-none"
                    @onclick="() => SubmitRating(star)"
                    disabled="@submitted"
                    title="@star star(s)">
                @(star <= selectedRating ? "★" : "☆")
            </button>
        }
    </div>
    @if (submitted)
    {
        <div class="alert alert-success mt-2" role="alert">
            Thanks! You rated this @selectedRating star(s).
        </div>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int selectedRating = 0;
    private bool submitted = false;

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@model.Title" has been added.
        <a href="/">Return to home</a>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="recipe-form">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="model.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Thai">Thai</option>
                <option value="Desserts">Desserts</option>
                <option value="Salads">Salads</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (comma-separated)</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="model.Ingredients"
                placeholder="Flour, Sugar, Butter, Apples, Cinnamon" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.Steps"
                placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;3. ..." />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission model = new();
    private bool submitted = false;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(model.Title) || string.IsNullOrWhiteSpace(model.Category))
            return;

        RecipeService.Submit(model);
        submitted = true;
    }
}

